132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        // Validate & normalize the optional email; reject the create when it is present but invalid.
146	        if (!normalizeEmail(ownerFieldsDto)) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        // Validate & normalize the optional postcode; reject the create when it is present but
150	        // not valid for the owner's city (see normalizePostcode).
151	        if (!normalizePostcode(ownerFieldsDto)) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
155	        // abbreviations) and store the normalized form back on the DTO so it is what gets
156	        // persisted and compared. Reject the create when the address is blank once normalized.
157	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
158	        if (canonicalAddress.isBlank()) {
159	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
160	        }
161	        ownerFieldsDto.setAddress(canonicalAddress);
162	        // Reject the create when the owner's city is already at capacity, i.e. it already
163	        // contains 50 or more owners (compared case-insensitively).
164	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
168	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
169	        if (normalizedTelephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        ownerFieldsDto.setTelephone(normalizedTelephone);
173	        // Consolidated duplicate detection. All former separate telephone, email and household
174	        // duplicate checks are now expressed through the single derived identity key
175	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
176	        // A create is rejected only when the new owner's identity collides with an existing owner's.
177	        // Because the telephone is part of the identity, two members of the same household with
178	        // different telephones no longer collide and are both allowed; only owners that share the
179	        // same normalized telephone and email are treated as the same identity.
180	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
181	        String contactIdentity = identityContact(candidate);
182	        boolean identityInUse = this.clinicService.findAllOwners().stream()
183	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
184	        if (identityInUse) {
185	            return new ResponseEntity<>(HttpStatus.CONFLICT);
186	        }
187	        // Determine the effective registration date — the value supplied on the request, or the
188	        // server's current date when none was supplied — and roll it forward to the next business
189	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
190	        // registration date (membership-number year segment, per-day create-limit) uses this
191	        // adjusted date.
192	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
193	        if (registrationDate == null) {
194	            registrationDate = LocalDate.now();
195	        }
196	        registrationDate = toBusinessDay(registrationDate);
197	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
198	        // owners have already been registered on this (adjusted) business day.
199	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Owner owner = candidate;
204	        owner.setRegistrationDate(registrationDate);
205	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
206	        // letters of the city, the upper-cased first three letters of the last name, and a
207	        // per-city 4-digit sequence one greater than the number of owners already in that city.
208	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
209	        // Record how many existing owners already share this owner's first and last name
210	        // (compared case-insensitively) at the moment before this owner is created.
211	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
212	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
213	        // registered on this (adjusted) business day before this owner is created.
214	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
215	        // Record the size of this owner's household after this create: the number of existing
216	        // owners sharing the same household (matching last name and address) plus this owner.
217	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
218	        this.clinicService.saveOwner(owner);
219	        // Emit an audit line recording the new owner's id, customer code, registration date
220	        // and membership level.
221	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
222	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
223	            ownerMapper.membershipLevel(owner));
224	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
225	        headers.setLocation(UriComponentsBuilder.newInstance()
226	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
227	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
228	    }
229	
230	    /**
231	     * Validate and normalize the optional owner email in place.
232	     *
233	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
234	     * When present it must be a syntactically valid address; a valid address is
235	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
236	     * present but syntactically invalid, so the caller can reject with 400.
237	     */
238	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
239	        String email = ownerFieldsDto.getEmail();
240	        if (email == null || email.isBlank()) {
241	            ownerFieldsDto.setEmail(null);
242	            return true;
243	        }
244	        String normalized = email.trim().toLowerCase(Locale.ROOT);
245	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
246	            return false;
247	        }
248	        ownerFieldsDto.setEmail(normalized);
249	        return true;
250	    }
251	
252	    /**
253	     * Validate the optional owner postcode in place.
254	     *
255	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
256	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
257	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
258	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
259	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
260	     * when a postcode is present but malformed or out of range, so the caller can
261	     * reject with 400.
262	     */
263	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
264	        String postcode = ownerFieldsDto.getPostcode();
265	        if (postcode == null || postcode.isBlank()) {
266	            ownerFieldsDto.setPostcode(null);
267	            return true;
268	        }
269	        if (!postcode.matches("\\d{4}")) {
270	            return false;
271	        }
272	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
273	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
274	        if (range != null) {
275	            int value = Integer.parseInt(postcode);
276	            if (value < range[0] || value > range[1]) {
277	                return false;
278	            }
279	        }
280	        return true;
281	    }
282	
283	    /**
284	     * Normalize an owner address: trim, collapse each run of whitespace to a single
285	     * space, upper-case, and expand common street-type abbreviations
286	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
287	     * A {@code null} value normalizes to the empty string.
288	     */
289	    private static String normalizeAddress(String value) {
290	        if (value == null) {
291	            return "";
292	        }
293	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
294	        if (collapsed.isEmpty()) {
295	            return "";
296	        }
297	        String[] tokens = collapsed.split(" ");
298	        StringBuilder sb = new StringBuilder(collapsed.length());
299	        for (int i = 0; i < tokens.length; i++) {
300	            if (i > 0) {
301	                sb.append(' ');
302	            }
303	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
304	        }
305	        return sb.toString();
306	    }
307	
308	    /**
309	     * The contact portion of an owner's derived identity key: its normalized telephone and
310	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
311	     * without the household segment. Two owners share an identity when this value is equal;
312	     * because the telephone is part of it, members of one household with different telephones
313	     * do not collide. A {@code null} email contributes the empty string.
314	     */
315	    private static String identityContact(Owner owner) {
316	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
317	        String email = owner.getEmail() == null ? "" : owner.getEmail();
318	        return telephone + "|" + email;
319	    }
320	
321	    /**
322	     * Normalize an owner household field (last name or address) for duplicate detection:
323	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
324	     * A {@code null} value normalizes to the empty string.
325	     */
326	    private static String normalizeHouseholdKey(String value) {
327	        if (value == null) {
328	            return "";
329	        }
330	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
331	    }
332	
333	    /**
334	     * Normalize a telephone number to E.164 form.
335	     *
336	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
337	     * explicit leading {@code '+'} and country code it is kept; otherwise the
338	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
339	     * dropped from the national digits. The result must contain 8 to 15 digits
340	     * after the {@code '+'}, and — for a recognised country calling code — exactly
341	     * the national-number length that code mandates ({@code '+61'} => 9 national
342	     * digits, {@code '+1'} => 10).
343	     *
344	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
345	     *         the input is absent or cannot form a valid E.164 number.
346	     */
347	    private static String toE164(String raw) {
348	        if (raw == null) {
349	            return null;
350	        }
351	        String trimmed = raw.trim();
352	        boolean hasCountryCode = trimmed.startsWith("+");
353	        // Strip spaces, dashes and brackets.
354	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
355	        String digits;
356	        if (hasCountryCode) {
357	            // Keep the explicit country code; drop the leading '+' for validation.
358	            digits = stripped.substring(1);
359	        } else {
360	            // No country code: assume '+61' and drop a single leading '0'.
361	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
362	            digits = "61" + national;
363	        }
364	        if (!digits.matches("\\d{8,15}")) {
365	            return null;
366	        }
367	        // For a recognised country calling code, enforce the exact national-number length it
368	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
369	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
370	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
371	                .sorted((a, b) -> b.length() - a.length()).toList()) {
372	            if (digits.startsWith(countryCode)) {
373	                int nationalLength = digits.length() - countryCode.length();
374	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
375	                    return null;
376	                }
377	                break;
378	            }
379	        }
380	        return "+" + digits;
381	    }
382	
383	    /**
384	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
385	     *
386	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
387	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
388	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
389	     * equal to one more than the number of owners already in that city
390	     * (e.g. {@code 'SYD-SMI-0007'}).
391	     */
392	    /**
393	     * Count the existing owners whose first and last name match the given names,
394	     * compared case-insensitively. Used to record an owner's namesake count at the
395	     * moment before it is created.
396	     */
397	    private int countNamesakes(String firstName, String lastName) {
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> existing.getFirstName() != null
400	                && existing.getFirstName().equalsIgnoreCase(firstName)
401	                && existing.getLastName() != null
402	                && existing.getLastName().equalsIgnoreCase(lastName))
403	            .count();
404	    }
405	
406	    /**
407	     * Count the existing owners in the same household as the given last name and address
408	     * (compared after household-key normalization). Used, together with the owner being
409	     * created, to derive the household size recorded on the owner.
410	     */
411	    private int countHouseholdMembers(String lastName, String address) {
412	        String normalizedLastName = normalizeHouseholdKey(lastName);
413	        String normalizedAddress = normalizeHouseholdKey(address);
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(existing ->
416	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
417	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
418	            .count();
419	    }
420	
421	    private String nextCustomerCode(String city, String lastName) {
422	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
423	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
424	        int sequence = countOwnersInCity(city) + 1;
425	        return String.format("%s-%s-%04d", city3, last3, sequence);
426	    }
427	
428	    /**
429	     * Count the existing owners located in the given city, compared case-insensitively.
430	     * Used to derive the per-city 4-digit sequence in the customer code.
431	     */
432	    private int countOwnersInCity(String city) {
433	        return (int) this.clinicService.findAllOwners().stream()
434	            .filter(existing -> existing.getCity() != null
435	                && existing.getCity().equalsIgnoreCase(city))
436	            .count();
437	    }
438	
439	    /**
440	     * Count the existing owners whose registration date is the given (adjusted business) date.
441	     * Used to enforce the per-day sign-up limit.
442	     */
443	    private int countOwnersRegisteredOn(LocalDate date) {
444	        return (int) this.clinicService.findAllOwners().stream()
445	            .filter(existing -> date.equals(existing.getRegistrationDate()))
446	            .count();
447	    }
448	
449	    /**
450	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
451	     * the following Monday; a weekday is returned unchanged.
452	     */
453	    private static LocalDate toBusinessDay(LocalDate date) {
454	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
455	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
456	            date = date.plusDays(1);
457	        }
458	        return date;
459	    }
