461	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
462	    @Override
463	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
464	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
465	        if (currentOwner == null) {
466	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
467	        }
468	        if (!normalizeEmail(ownerFieldsDto)) {
469	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
470	        }
471	        if (!normalizePostcode(ownerFieldsDto)) {
472	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
473	        }
474	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
475	        if (normalizedTelephone == null) {
476	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
477	        }
478	        currentOwner.setAddress(ownerFieldsDto.getAddress());
479	        currentOwner.setCity(ownerFieldsDto.getCity());
480	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
481	        currentOwner.setLastName(ownerFieldsDto.getLastName());
482	        currentOwner.setTelephone(normalizedTelephone);
483	        currentOwner.setEmail(ownerFieldsDto.getEmail());
484	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
485	        this.clinicService.saveOwner(currentOwner);
486	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
487	    }
