4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Locale;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's locality. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    /**
29	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by region
30	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), used to derive an owner's
31	     * locality from the postcode in preference to the city.
32	     */
33	    java.util.Map<String, int[]> REGION_POSTCODE_RANGES =
34	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
35	            "QLD", new int[] {4000, 4099});
36	
37	    @Mapping(target = "displayName",
38	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
39	    @Mapping(target = "initials", expression = "java(initials(owner))")
40	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
41	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
42	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
43	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
44	    @Mapping(target = "locality", expression = "java(locality(owner))")
45	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
46	    OwnerDto toOwnerDto(Owner owner);
47	
48	    /**
49	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
50	     * otherwise 'PHONE'.
51	     */
52	    default String contactPreference(Owner owner) {
53	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
54	        return hasEmail ? "EMAIL" : "PHONE";
55	    }
56	
57	    /**
58	     * The canonical region derived for the owner, preferring the postcode. The
59	     * postcode is matched against each region's inclusive range (NSW 2000-2099,
60	     * VIC 3000-3099, QLD 4000-4099) first; only when the postcode is absent or in
61	     * no known range does this fall back to the fixed city-to-region table
62	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns 'UNKNOWN' when neither
63	     * the postcode nor the city resolves to a region.
64	     */
65	    default String locality(Owner owner) {
66	        String byPostcode = regionForPostcode(owner.getPostcode());
67	        if (byPostcode != null) {
68	            return byPostcode;
69	        }
70	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
71	    }
72	
73	    /**
74	     * The region whose inclusive postcode range contains {@code postcode}, or
75	     * {@code null} when the postcode is absent, not a 4-digit number, or in no
76	     * known range.
77	     */
78	    private static String regionForPostcode(String postcode) {
79	        if (postcode == null || !postcode.matches("\\d{4}")) {
80	            return null;
81	        }
82	        int value = Integer.parseInt(postcode);
83	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
84	            int[] range = entry.getValue();
85	            if (value >= range[0] && value <= range[1]) {
86	                return entry.getKey();
87	            }
88	        }
89	        return null;
90	    }
91	
92	    /**
93	     * The owner's numeric membership level, assigned on creation. It starts at 1, gains
94	     * 1 when an email address is present, and gains 1 when the owner has no namesakes
95	     * (namesakeCount is 0), capped at 3. Level 4 is reserved for tenure.
96	     */
97	    default Integer membershipLevel(Owner owner) {
98	        int level = 1;
99	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
100	        if (hasEmail) {
101	            level++;
102	        }
103	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
104	        if (noNamesakes) {
105	            level++;
106	        }
107	        return Math.min(level, 3);
108	    }
109	
110	    /**
111	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
112	     * is the last two digits of the registrationDate year (e.g. 'SYD-SMI-0007-M26').
113	     */
114	    default String membershipNumber(Owner owner) {
115	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
116	            return null;
117	        }
118	        return String.format("%s-M%02d", owner.getCustomerCode(),
119	            owner.getRegistrationDate().getYear() % 100);
120	    }
121	
122	    /**
123	     * The upper-cased first letters of firstName and lastName, dot-separated with a
124	     * trailing dot, e.g. 'J.S.'.
125	     */
126	    default String initials(Owner owner) {
127	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
128	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
129	    }
130	
131	    /**
132	     * A stable identifier for the owner's household, derived deterministically from the
133	     * normalized last name and address (trimmed, lower-cased, whitespace collapsed).
134	     * Every owner sharing a household therefore receives the same identifier: the first
135	     * eight upper-case hex characters of the SHA-256 of '&lt;lastName&gt;|&lt;address&gt;'.
136	     */
137	    default String householdId(Owner owner) {
138	        String key = normalizeHouseholdKey(owner.getLastName()) + "|"
139	            + normalizeHouseholdKey(owner.getAddress());
140	        try {
141	            byte[] digest = MessageDigest.getInstance("SHA-256")
142	                .digest(key.getBytes(StandardCharsets.UTF_8));
143	            StringBuilder sb = new StringBuilder();
144	            for (int i = 0; i < 4; i++) {
145	                sb.append(String.format("%02X", digest[i]));
146	            }
147	            return sb.toString();
148	        }
149	        catch (java.security.NoSuchAlgorithmException e) {
150	            throw new IllegalStateException(e);
151	        }
152	    }
153	
154	    /**
155	     * The owner's derived identity key: the single value onto which all duplicate
156	     * detection is consolidated, formatted
157	     * '&lt;normalizedTelephone&gt;|&lt;email or empty&gt;|&lt;householdId&gt;'.
158	     * The telephone and email are the owner's stored (already normalized) values;
159	     * a {@code null} email contributes the empty string. Two owners are duplicates
160	     * only when their whole identity keys are equal.
161	     */
162	    default String identityKey(Owner owner) {
163	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
164	        String email = owner.getEmail() == null ? "" : owner.getEmail();
165	        return telephone + "|" + email + "|" + householdId(owner);
166	    }
167	
168	    private static String normalizeHouseholdKey(String value) {
169	        if (value == null) {
170	            return "";
171	        }
172	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
173	    }
174	
175	    Owner toOwner(OwnerDto ownerDto);
176	
177	    @Mapping(target = "id", ignore = true)
178	    @Mapping(target = "pets", ignore = true)
179	    Owner toOwner(OwnerFieldsDto ownerDto);
180	
181	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
182	
183	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
184	
185	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
186	        OwnerPageDto ownerPageDto = new OwnerPageDto();
187	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
188	        ownerPageDto.setPage(ownerPage.getNumber());
189	        ownerPageDto.setSize(ownerPage.getSize());
190	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
191	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
192	        return ownerPageDto;
193	    }
194	}
